{
   "title": "ExternalTransaction",
   "description": "Dataclass containing information on an external transaction (eg money movement).",
   "type": "object",
   "properties": {
      "id": {
         "title": "Id",
         "type": "integer"
      },
      "account-number": {
         "title": "Account-Number",
         "type": "string"
      },
      "amount": {
         "anyOf": [
            {
               "type": "number"
            },
            {
               "type": "string"
            }
         ],
         "title": "Amount"
      },
      "bank-account-type": {
         "title": "Bank-Account-Type",
         "type": "string"
      },
      "banking-date": {
         "format": "date",
         "title": "Banking-Date",
         "type": "string"
      },
      "created-at": {
         "format": "date-time",
         "title": "Created-At",
         "type": "string"
      },
      "direction": {
         "title": "Direction",
         "type": "string"
      },
      "disbursement-type": {
         "title": "Disbursement-Type",
         "type": "string"
      },
      "ext-transfer-id": {
         "title": "Ext-Transfer-Id",
         "type": "string"
      },
      "funds-available-date": {
         "format": "date",
         "title": "Funds-Available-Date",
         "type": "string"
      },
      "is-cancelable": {
         "title": "Is-Cancelable",
         "type": "boolean"
      },
      "is-clearing-accepted": {
         "title": "Is-Clearing-Accepted",
         "type": "boolean"
      },
      "state": {
         "title": "State",
         "type": "string"
      },
      "transfer-method": {
         "title": "Transfer-Method",
         "type": "string"
      },
      "updated-at": {
         "format": "date-time",
         "title": "Updated-At",
         "type": "string"
      }
   },
   "required": [
      "id",
      "account-number",
      "amount",
      "bank-account-type",
      "banking-date",
      "created-at",
      "direction",
      "disbursement-type",
      "ext-transfer-id",
      "funds-available-date",
      "is-cancelable",
      "is-clearing-accepted",
      "state",
      "transfer-method",
      "updated-at"
   ]
}

